'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createStore } = require('../src/store');
const { createTicket, resolveTicket } = require('../src/tickets');
const { closeResolved } = require('../src/jobs/close-resolved');
const portal = require('../src/portal');

const DAY = 24 * 60 * 60 * 1000;
const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
const acme = { id: 7, orgId: 1 };
const globex = { id: 9, orgId: 2 };

function resolvedTicket(store) {
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now: at(0) });
  resolveTicket(store, t.id, 41, { now: at(1) });
  return t;
}

test('a customer rates a resolved ticket of their organisation, and the rating is stored with the ticket', () => {
  const store = createStore();
  const t = resolvedTicket(store);
  const out = portal.rateMyTicket(store, acme, t.id, 4, { now: at(2) });
  assert.equal(out.rating_score, 4);
  assert.equal(out.rated_at, at(2).toISOString());
  assert.equal(store.getTicket(t.id).rating_score, 4);
});

test('a new ticket has no rating', () => {
  const t = createTicket(createStore(), { orgId: 1, customerId: 7, subject: 'a', body: 'b' });
  assert.equal(t.rating_score, null);
  assert.equal(t.rated_at, null);
});

test('a score that is not a whole number from 1 to 5 is refused', () => {
  const store = createStore();
  const t = resolvedTicket(store);
  for (const bad of [0, 6, 3.5, '4', null, undefined, NaN, -1]) {
    assert.throws(() => portal.rateMyTicket(store, acme, t.id, bad), /whole number from 1 to 5/, String(bad));
  }
  assert.equal(store.getTicket(t.id).rating_score, null);
});

test('an open, pending or closed ticket cannot be rated', () => {
  const store = createStore();
  const open = createTicket(store, { orgId: 1, customerId: 7, subject: 'a', body: 'b', now: at(0) });
  assert.throws(() => portal.rateMyTicket(store, acme, open.id, 5), /cannot rate a open ticket/);
  store.updateTicket(open.id, { status: 'pending' });
  assert.throws(() => portal.rateMyTicket(store, acme, open.id, 5), /cannot rate a pending ticket/);
  const t = resolvedTicket(store);
  closeResolved(store, { now: at(5) });
  assert.throws(() => portal.rateMyTicket(store, acme, t.id, 5), /cannot rate a closed ticket/);
});

test('a second rating is refused and the first stays', () => {
  const store = createStore();
  const t = resolvedTicket(store);
  portal.rateMyTicket(store, acme, t.id, 4, { now: at(2) });
  assert.throws(() => portal.rateMyTicket(store, acme, t.id, 1, { now: at(3) }), /already been rated/);
  const after = store.getTicket(t.id);
  assert.equal(after.rating_score, 4);
  assert.equal(after.rated_at, at(2).toISOString());
});

test('another organisation gets the same answer as for a ticket that does not exist', () => {
  const store = createStore();
  const t = resolvedTicket(store);
  const missing = portal.rateMyTicket(store, globex, 9999, 4);
  assert.equal(missing, null);
  assert.equal(portal.rateMyTicket(store, globex, t.id, 4), null);
  assert.equal(portal.rateMyTicket(store, globex, t.id, 99), null);
  assert.equal(store.getTicket(t.id).rating_score, null);
