    setRatingOnce(id, rating) {
      const t = tickets.get(id);
      if (!t) throw new Error(`no ticket ${id}`);
      if (t.rating_score != null) return false;
      Object.assign(t, rating);
      return true;
    },
```
Evidence: `npm test` unchanged (still the step 1 failures).
- [ ] 3. In `src/tickets.js` add `rating_score: null,` and `rated_at: null,` after `closed_at: null,` in `createTicket`. Add before `mustGet`:
```js
const MIN_SCORE = 1;
const MAX_SCORE = 5;

function recordRating(store, id, score, { now = new Date() } = {}) {
  if (!Number.isInteger(score) || score < MIN_SCORE || score > MAX_SCORE) throw new Error('a rating is a whole number from 1 to 5');
  const t = mustGet(store, id);
  if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
  if (!store.setRatingOnce(id, { rating_score: score, rated_at: now.toISOString() })) throw new Error('this ticket has already been rated');
  return store.getTicket(id);
}
```
and add `recordRating` to `module.exports`. Evidence: `npm test`: "a new ticket has no rating" passes; the others still fail on `rateMyTicket`.
- [ ] 4. In `src/portal.js` change the require to `const { STATUS, createTicket, recordRating } = require('./tickets');`, add before `module.exports`:
```js
// The customer rates a resolved ticket of their organisation, once. Another organisation's ticket and a missing one
// both give null, and that check comes before anything else, so the answer does not tell them apart.
function rateMyTicket(store, customer, id, score, { now = new Date() } = {}) {
  if (!getMyTicket(store, customer, id)) return null;
  recordRating(store, id, score, { now });
  return getMyTicket(store, customer, id);
}
```
and add `rateMyTicket` to `module.exports`. Run `npm test`. Evidence: all green, pasted.
