'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createStore } = require('../src/store');
const { createTicket, assignTicket, resolveTicket } = require('../src/tickets');
const portal = require('../src/portal');
const { summariseRatings, writeWeeklyRatingSummary } = require('../src/jobs/weekly-rating-summary');

const DAY = 24 * 60 * 60 * 1000;
const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
const acme = { id: 7, orgId: 1 };

function ratedTicket(store, agent, score, ratedDay) {
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 's', body: 'b', now: at(0) });
  if (agent) assignTicket(store, t.id, agent);
  resolveTicket(store, t.id, 41, { now: at(ratedDay) });
  portal.rateMyTicket(store, acme, t.id, score, { now: at(ratedDay) });
}

test('ratings 5, 4 and 1 in the past seven days give three ratings and 3.33; an eight day old one is not counted', () => {
  const store = createStore();
  for (const [score, day] of [[5, 20], [4, 18], [1, 14]]) ratedTicket(store, 41, score, day);
  ratedTicket(store, 41, 2, 12); // eight days before day 20
  assert.deepEqual(summariseRatings(store, { now: at(20) }), [{ agent_id: 41, ratings: 3, average: 3.33 }]);
});

test('each agent is summarised on their own; unrated and unowned tickets are skipped', () => {
  const store = createStore();
  ratedTicket(store, 41, 5, 10);
  ratedTicket(store, 42, 2, 10);
  ratedTicket(store, 42, 3, 10);
  ratedTicket(store, null, 1, 10);
  createTicket(store, { orgId: 1, customerId: 7, subject: 'unrated', body: 'b', now: at(0) });
  assert.deepEqual(summariseRatings(store, { now: at(11) }), [
    { agent_id: 41, ratings: 1, average: 5 },
    { agent_id: 42, ratings: 2, average: 2.5 },
  ]);
});

test('a rating exactly seven days old still counts, one second older does not', () => {
  const store = createStore();
  ratedTicket(store, 41, 4, 10);
  assert.equal(summariseRatings(store, { now: at(17) }).length, 1);
  assert.equal(summariseRatings(store, { now: new Date(at(17).getTime() + 1000) }).length, 0);
});

test('the job writes reports/agent-ratings.json', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-report-'));
  try {
    const store = createStore();
    ratedTicket(store, 41, 5, 10);
    const out = writeWeeklyRatingSummary(store, { now: at(11), dir });
    assert.equal(out.agents, 1);
    const body = JSON.parse(fs.readFileSync(out.file, 'utf8'));
    assert.deepEqual(body, { generated_at: at(11).toISOString(), window_days: 7, agents: [{ agent_id: 41, ratings: 1, average: 5 }] });
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});
```
Run `npm test`. Evidence: the new file fails with `Cannot find module '../src/jobs/weekly-rating-summary'`.
- [ ] 2. Create `src/jobs/weekly-rating-summary.js`:
```js
'use strict';
// Nightly. Writes reports/agent-ratings.json: for each agent, how many ratings their tickets received in the past
// seven days and the average score. A rolling window, recomputed every night. The agent is the ticket's current owner.
const fs = require('node:fs');
const path = require('node:path');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;
const REPORT_DIR = path.join(__dirname, '..', '..', 'reports');

function summariseRatings(store, { now = new Date() } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.rating_score == null || !t.owner_id) continue;
    if (new Date(t.rated_at).getTime() < since) continue;
    const s = byAgent.get(t.owner_id) || { sum: 0, ratings: 0 };
    s.sum += t.rating_score;
    s.ratings += 1;
    byAgent.set(t.owner_id, s);
  }
  return [...byAgent.entries()]
    .sort(([a], [b]) => a - b)
    .map(([agentId, s]) => ({ agent_id: agentId, ratings: s.ratings, average: Math.round((s.sum / s.ratings) * 100) / 100 }));
}

function writeWeeklyRatingSummary(store, { now = new Date(), dir = REPORT_DIR } = {}) {
  const agents = summariseRatings(store, { now });
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'agent-ratings.json');
  fs.writeFileSync(file, JSON.stringify({ generated_at: now.toISOString(), window_days: WINDOW_DAYS, agents }, null, 2) + '\n');
  return { file, agents: agents.length };
}

module.exports = { summariseRatings, writeWeeklyRatingSummary, WINDOW_DAYS, REPORT_DIR };
```
